<section class="attention-page activity-log-page" x-data="resourcePage({ endpoint: 'logs', columns: [], perPage: 10 })" x-init="load()" aria-label="System Activity Logs">
    <div class="attention-stats" aria-label="Activity summary for current filters">
        @foreach ([['activities', 'Activities', 'activity', 'purple'], ['security', 'Security events', 'lock-keyhole', 'blue'], ['denied', 'Access denied', 'triangle-alert', 'danger']] as [$key, $label, $icon, $color])
            <article class="metric-stat-card"><div class="metric-info"><span class="metric-label">{{ $label }}</span><strong class="metric-number color-dark" x-text="summary?.{{ $key }} ?? '—'"></strong></div><div class="metric-icon-box {{ $color }}"><i data-lucide="{{ $icon }}" aria-hidden="true"></i></div></article>
        @endforeach
    </div>
    <div class="attention-tabs" role="group" aria-label="Event category">
        @foreach(['' => 'All Activity', 'authentication' => 'Authentication', 'documents' => 'Documents', 'audits' => 'Audit Actions', 'security' => 'Security', 'accounts' => 'Accounts', 'organization' => 'Organization', 'permissions' => 'Permissions', 'notifications' => 'Notifications', 'system' => 'System'] as $value => $label)
            <button type="button" @click="categoryFilter = '{{ $value }}'; load(1)" :aria-pressed="categoryFilter === '{{ $value }}'" :class="{ 'is-active': categoryFilter === '{{ $value }}' }">{{ $label }}</button>
        @endforeach
    </div>
    <div class="attention-log-filters"><label>Search events<input type="search" placeholder="Search recorded activity…" maxlength="200" x-model="search" @input.debounce.350ms="load(1)"></label><label>Performed by<input type="search" placeholder="Actor name" maxlength="200" x-model="actorFilter" @input.debounce.350ms="load(1)"></label><label>Result<select x-model="outcomeFilter" @change="load(1)"><option value="">All results</option><option value="success">Success</option><option value="failed">Failed</option><option value="denied">Denied</option></select></label><label>Sort by<select x-model="sortBy" @change="load(1)" aria-label="Sort audit logs by"><option value="createdAt:desc">Newest first</option><option value="createdAt:asc">Oldest first</option><option value="action:asc">Event A–Z</option><option value="action:desc">Event Z–A</option><option value="userName:asc">Actor A–Z</option><option value="userName:desc">Actor Z–A</option><option value="entityType:asc">Record type A–Z</option></select></label></div>
    <div class="attention-history"><fieldset><legend>History range</legend><label>From<input type="date" x-model="draftStartDate" aria-label="History start date"></label><label>Through<input type="date" x-model="draftEndDate" :min="draftStartDate || null" aria-label="History end date"></label><button type="button" class="attention-button" @click="applyDateRange()" :disabled="loading">Apply</button><button type="button" class="attention-button" @click="clearDateRange()" :disabled="loading">Clear</button></fieldset><button type="button" class="attention-button is-primary" data-log-export @click="exportAuditLogs()" :disabled="exporting || loading"><i data-lucide="download" aria-hidden="true"></i><span x-text="exporting ? 'Exporting…' : 'Export CSV'"></span></button></div>
    <p class="attention-error" x-cloak x-show="dateRangeError || exportError" x-text="dateRangeError || exportError" role="alert"></p>
    <p class="attention-feedback" x-cloak x-show="successPopupVisible" x-text="successPopupMessage" role="status"></p>
    <div class="attention-error" x-cloak x-show="error" role="alert"><p x-text="error"></p><button type="button" class="attention-button" @click="load()">Try again</button></div>
    <div class="attention-loading" x-show="loading" role="status" aria-label="Loading system activity logs"><span class="sr-only">Loading system activity logs…</span><template x-for="item in 3" :key="item"><div class="attention-skeleton" aria-hidden="true"><span></span><span></span></div></template></div>
    <div class="attention-empty" x-cloak x-show="!loading && !error && !rows.length"><i data-lucide="scroll-text" aria-hidden="true"></i><h3>No matching activity</h3><p>Try another filter or history range.</p></div>
    <div class="attention-table-wrap" x-cloak x-show="!loading && !error && rows.length"><table class="attention-log-table"><thead><tr><th>Event</th><th>Performed by</th><th>Affected record</th><th>Category</th><th>Result</th><th>Date</th><th><span class="sr-only">Details</span></th></tr></thead><tbody><template x-for="log in rows" :key="log._id"><tr :data-log-id="log._id" :class="{ 'is-highlighted': logHighlightId === log._id }"><td data-label="Event" x-text="log.action"></td><td data-label="Performed by" x-text="log.userName"></td><td data-label="Affected record"><span x-text="formatValue(log.entityType)"></span><small x-text="log.entityId || '—'"></small></td><td data-label="Category"><span class="attention-pill" x-text="formatValue(log.category)"></span></td><td data-label="Result"><span class="attention-outcome" :class="`is-${log.outcome}`" x-text="formatValue(log.outcome)"></span></td><td data-label="Date"><time :datetime="log.createdAt" x-text="formatValue(log.createdAt)"></time></td><td data-label="Details"><button type="button" class="attention-button" @click="openRecordDetails(log)">View log details</button></td></tr></template></tbody></table></div>
    @include('components.partials.attention-pagination', ['label' => 'Activity log pages'])
    <dialog x-ref="recordDetails" class="attention-dialog activity-log-dialog" @click="if ($event.target === $el) $el.close()" @close="closeRecordDetails()" aria-labelledby="log-detail-heading"><header><div><p class="attention-eyebrow">SYSTEM ACTIVITY LOG · READ ONLY</p><h2 id="log-detail-heading">View Log Details</h2></div><button type="button" class="attention-button" @click="$refs.recordDetails.close()" aria-label="Close log details"><i data-lucide="x" aria-hidden="true"></i></button></header><div class="attention-dialog-body"><p x-show="detailLoading" role="status">Loading log details…</p><p class="attention-error" x-show="detailError" x-text="detailError" role="alert"></p><template x-if="details && !detailLoading"><div><h3 x-text="details.action"></h3><dl class="attention-detail-grid">@foreach(['userName' => 'Performed by', 'userId' => 'Actor ID', 'entityType' => 'Affected record type', 'entityId' => 'Affected record ID', 'category' => 'Category', 'outcome' => 'Result', 'createdAt' => 'Timestamp', 'ipAddress' => 'IP address', 'method' => 'Request method', 'route' => 'Application route', '_id' => 'Log ID'] as $field => $label)<div><dt>{{ $label }}</dt><dd x-text="formatValue(details['{{ $field }}'])"></dd></div>@endforeach</dl></div></template></div><footer><p>Historical record. Changes to notifications do not modify this log.</p><button type="button" class="attention-button is-primary" @click="$refs.recordDetails.close()">Close</button></footer></dialog>
</section>
